<script setup lang="ts">import{reactive,ref}from'vue';import ProductIdentityDisplay from './ProductIdentityDisplay.vue';import ChineseDatePicker from'./ChineseDatePicker.vue';import{receiveAfterSales,type AfterSalesDetail}from'../api/after-sales';const props=defineProps<{detail:AfterSalesDetail}>(),emit=defineEmits<{close:[];saved:[];message:[text:string,kind?:'success'|'error']}>();const date=ref(new Date().toISOString().slice(0,10));const items=reactive(props.detail.returnLines.map(x=>({line:x,goodQuantity:0,defectiveQuantity:0})));async function submit(){if(items.some(x=>x.goodQuantity+x.defectiveQuantity>x.line.requestedQuantity-(x.line.receivedQuantity??0))){emit('message','本次收货数量超过待收数量','error');return}try{await receiveAfterSales(props.detail.id,{receiptDate:date.value,version:props.detail.version,items:items.filter(x=>x.goodQuantity+x.defectiveQuantity>0).map(x=>({returnLineId:x.line.id,goodQuantity:x.goodQuantity,defectiveQuantity:x.defectiveQuantity}))});emit('saved')}catch(e){emit('message',e instanceof Error?e.message:'收货失败','error')}}</script><template><div class="dialog-mask"><section class="dialog-card after-sales-action-dialog"><header><div><h2>确认退货收货</h2><p>良品进入可用库存，不良品只保留质检记录</p></div><button @click="emit('close')">关闭</button></header><div class="after-sales-body"><label><span>收货日期</span><ChineseDatePicker v-model="date" /></label><div v-for="x in items" :key="x.line.id" class="after-sales-quality-line"><ProductIdentityDisplay compact :product-code="x.line.productCode" :customer-part-number="x.line.customerPartNumber" :model="x.line.model" /><span>待收 {{x.line.requestedQuantity-(x.line.receivedQuantity??0)}}</span><label>良品<input v-model.number="x.goodQuantity" type="number" min="0"></label><label>不良品<input v-model.number="x.defectiveQuantity" type="number" min="0"></label></div></div><footer class="dialog-actions"><button class="secondary-action" @click="emit('close')">取消操作</button><button class="primary-action" @click="submit">确认收货</button></footer></section></div></template>
